<?php
require_once 'functions.php';require_login();$q=$pdo->prepare('SELECT is_admin FROM users WHERE id=?');$q->execute([$_SESSION['user_id']]);if(!(int)$q->fetchColumn()){http_response_code(403);page_header('Administration');echo '<section class="page-intro"><h1>Accès réservé</h1><p>Cette page est réservée aux comptes administrateurs.</p></section>';page_footer();exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['close_report'])){$q=$pdo->prepare("UPDATE reports SET status='closed' WHERE id=?");$q->execute([(int)$_POST['close_report']]);header('Location: admin.php');exit;}
$reports=$pdo->query('SELECT r.*,u.username FROM reports r JOIN users u ON u.id=r.reporter_id ORDER BY r.created_at DESC')->fetchAll();$counts=$pdo->query('SELECT (SELECT COUNT(*) FROM users) users_count,(SELECT COUNT(*) FROM artists) artists_count,(SELECT COUNT(*) FROM reports WHERE status=\'open\') open_reports')->fetch();page_header('Administration'); ?><section class="page-intro"><div class="eyebrow">GESTION SONORA</div><h1>Administration</h1></section><div class="stat-grid"><div class="panel"><h3>Membres</h3><strong><?= (int)$counts['users_count'] ?></strong></div><div class="panel"><h3>Artistes</h3><strong><?= (int)$counts['artists_count'] ?></strong></div><div class="panel"><h3>Signalements ouverts</h3><strong><?= (int)$counts['open_reports'] ?></strong></div></div><section class="section-head"><h2>Signalements</h2></section><div class="news-list"><?php foreach($reports as $r): ?><article class="news-card"><div class="news-meta">#<?= (int)$r['id'] ?> · <?= e($r['username']) ?> · <?= e($r['status']) ?> · <?= e($r['target_type']) ?></div><p><?= nl2br(e($r['reason'])) ?></p><?php if($r['status']!=='closed'): ?><form method="post"><button class="button secondary" name="close_report" value="<?= (int)$r['id'] ?>">Marquer comme traité</button></form><?php endif; ?></article><?php endforeach; ?><?php if(!$reports): ?><article class="news-card">Aucun signalement.</article><?php endif; ?></div><?php page_footer(); ?>